        return ''.join(ans)

class Solution {
public:
    string reformat(string s) {
        string a = "", b = "";
        for (char c : s) {
            if (isdigit(c))
                a += c;
            else
                b += c;
        }
        int m = a.size(), n = b.size();
        if (abs(m - n) > 1) return "";
        string ans = "";
        for (int i = 0; i < min(m, n); ++i) {
            if (m > n) {
                ans += a[i];
                ans += b[i];
            } else {
                ans += b[i];
                ans += a[i];
            }
        }
        if (m > n) ans += a[m - 1];
        if (m < n) ans += b[n - 1];
        return ans;
    }
};

function reformat(s: string): string {
    let a: string[] = [];
    let b: string[] = [];

    for (const c of s) {
        if (c >= 'a' && c <= 'z') a.push(c);
        else if (c >= '0' && c <= '9') b.push(c);
    }

    if (Math.abs(a.length - b.length) > 1) {
        return '';
    }

    if (a.length < b.length) {
        [a, b] = [b, a];
    }

    const ans: string[] = [];

    for (let i = 0; i < b.length; i++) {
        ans.push(a[i] + b[i]);
    }

    if (a.length > b.length) {
        ans.push(a[a.length - 1]);
    }

    return ans.join('');
}

